head.script:
/* 동산 매각물건 상세 화면 */

/* 프로그램ID */
scwin.pgmId = 'PGJ15BM04';

scwin.srchInfo = {};
scwin.prevPgmId = "";

/* 기본정보 */
scwin.baseInfo = "";

/* 검색조건 */
scwin.param;
scwin.pageSize;
scwin.pageNum = '';

/* 최상단(opener, parent 포함) 기준 함수 */
scwin.isMain = function() {
    return true;
};

/**
 *  경매공고, 경매물건, 나의경매 화면 구분코드에 따라 화면 페이지 셋팅
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.01.06.   나해준       [NELS]최초 생성
 *  2025.12.26.   공태은       [25A-PGJ-0053] 나의경매 자주쓰는검색 화면에서 페이지 이동시 검색조건이 초기화되는 현상 수정
 * ============= ============ ==========================
 */
scwin.onpageload = function() {
    scwin.param = com.getParameter('param');
    scwin.prevPgmId = scwin.param ?. pgmId || scwin.param.srchInfo ?. pgmId
    const sideDvsCd = scwin.param.srchInfo ?. sideDvsCd
    const menuNm = scwin.param.srchInfo ?. menuNm;
    scwin.pageNum = scwin.param.prevInfo ?. pageNum || 1;

    let sidePath = '';
    let topTitle = '';
    switch(sideDvsCd){
        case '1' : sidePath = '../common/sideMenu/side001.xml'
            topTitle = '경매공고'
            break;
        case '2' : sidePath = '../common/sideMenu/side002.xml'
            topTitle = '경매물건'
            break;
//        case '3' : sidePath = '../common/sideMenu/side003.xml'
//            topTitle = '매각통계'
//            break;
//        case '4' : sidePath = '../common/sideMenu/side004.xml'
//            topTitle = '경매지식'
//            break;
//        case '5' : sidePath = '../common/sideMenu/side005.xml'
//            topTitle = '이용안내'
//            break;
        case '3' : sidePath = '../common/sideMenu/side006.xml'
            topTitle = '나의경매'
            break;
    }
    wfm_sideBox.setSrc(sidePath);

    /* 메뉴 */
    if (!scutilo.isEmpty(scwin.prevPgmId)) {
        if(sideDvsCd == '3'){
            $p.main().wfm_mainFrame.scope.wfm_sideBox.scope.scwin.menuFocus('PGJ195');
        }else{
            $p.main().wfm_mainFrame.scope.wfm_sideBox.scope.scwin.menuFocus(scwin.prevPgmId.slice(0, 6));
        }
    }

	tbx_mainTitle.setValue(menuNm);
    spn_topTitle.setValue(topTitle);
    spn_topTitle2.setValue(menuNm);

    dma_srchGdsinfo.setJSON({
        cortOfcCd : scwin.param.cortOfcCd || scwin.param.srchInfo ?. cortOfcCd ,
        csNo : scwin.param.csNo || scwin.param.srchInfo ?. csNo ,
        mvprpCsNo : scwin.param.mvSaNo || scwin.param.srchInfo ?. mvprpCsNo ,
        dspslGdsSeq : scwin.param.dspslGdsSeq || scwin.param.srchInfo ?. dspslGdsSeq
    })
    scwin.pageSize =20;
    if (pgjUtil.getCookie('pageCnt')) {
        scwin.pageSize = Number(pgjUtil.getCookie('pageCnt'));
    }
    /* 전자사건 여부 hide */
    spn_elctnCs.hide();
    grp_rdngPlc.hide();
    sbx_mvprpGdsPage.setValue(scwin.pageSize);
    scwin.mvprpGdsInfoPagingMain(true, scwin.pageSize);
};

scwin.onpageunload = function() {

};

//웹접근성으로 인한 title제공 수정
scwin.titleFormatter = function(){
    return "";
}

/**
 * 페이징 처리 Main
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.15.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.mvprpGdsInfoPagingMain = function(isFirst,pageNum){

    /* 최초 조회 여부 */
    if (isFirst) {
        dma_pageInfo.set("pageNo" , 1);
        dma_pageInfo.set("totalYn", "Y");
    } else {
        dma_pageInfo.set("totalYn", "N");
    }
    /* 페이지 사이즈 셋팅 */
    dma_pageInfo.set("pageSize", pageNum);
    com.executeSubmission(sbm_mvprpGdsDtlInf);
}
scwin.sbm_mvprpGdsDtlInf_submitdone = function({responseJSON:{data,message,status}}) {
    document.body.scrollTop = 0;
    if (status === 200) {
        const {result,dlt_mvprpGdsLst} = data;
        const baseInfo = result.mvprpBaseInfo;
        const cncrncCsLst = result.cncrncCsLst;
        const mvprpGdsInfo = result.mvprpGdsInfo;
        const atchmPlc = result.atchmPlc;
        if (baseInfo) {
            spn_cortSptNm.setValue(baseInfo.cortSptNm)
            spn_baseCsNo.setValue(baseInfo.mvprpCsNo)
            /* 사건번호 */
            if (baseInfo.lwstDvsCd === "2") spn_elctnCs.show("")
            spn_mvprpCsNo.setValue(baseInfo.mvprpCsNo);
            /* 집행담당관 */
            spn_chargExecr.setValue(`${baseInfo.cortAuctnJdbnNm} ${baseInfo.chargrNm}`)
            /* 경합사건 */
            if (cncrncCsLst.length >0) {
                let printNm = ""
                cncrncCsLst.forEach(data => {
                    printNm += `${data.mvprpCsNo} `;
                    // 02 : 정지 ,03 : 취소, 04 : 취하
                    if (data.csProgStatCd === '0002100002'
                            || data.csProgStatCd === '0002100003'
                            || data.csProgStatCd === '0002100004') {
                        printNm += `(${pgjUtil.getSTGcodeSystemNm('PGJ','CS_PROG_STAT_CD',data.csProgStatCd)})`
                    }
                })
                spn_cncrncCs.setValue(printNm);
            } else {
                tr_cncrncCs.hide();
            }
            /* 집행관 사무소 */
            let printOfcNm = baseInfo.cortOfcNm;
            if (baseInfo.cortTypCd === '70') printOfcNm += ` ${baseInfo.cortSptNm.replaceAll('대구','').replaceAll('부산','')}`;
            spn_sptNm.setValue(printOfcNm);

            scwin.baseInfo = baseInfo;
        }
        let preRdngNm = '사전열람사항이 없습니다.'
        if (!scutilo.isEmpty(mvprpGdsInfo.spotRdngYmd)) {
            /* 열람 시간 */
            preRdngNm = `개방시간 : ${scdateo.getFmtDate(mvprpGdsInfo.spotRdngYmd,".")} ${scwin.timeFormat(mvprpGdsInfo.spotRdngBgngHm)}`
            preRdngNm += ` ~ ${scdateo.getFmtDate(mvprpGdsInfo.spotRdngYmd,".")} ${scwin.timeFormat(mvprpGdsInfo.spotRdngEndHm)}`
            grp_rdngPlc.show("");

            /* 열람 장소 */
            let rdngPlcNm = ""
            if (!scutilo.isEmpty(mvprpGdsInfo.spotRdngAddrTypCd) && mvprpGdsInfo.spotRdngAddrTypCd === 'R') {
                rdngPlcNm = `${mvprpGdsInfo.hreadRegnRdnmSdNm || ''} ${mvprpGdsInfo.hreadRegnRdnmSggNm || ''}`
                rdngPlcNm += ` ${mvprpGdsInfo.spotRdngRdnmEmdNm || ""} ${mvprpGdsInfo.hreadRegnRdnm}`
                rdngPlcNm += ` ${mvprpGdsInfo.spotRdngDtlAddr || ""}`
                rdngPlcNm += !scutilo.isEmpty(mvprpGdsInfo.spotRdngRdnmDtlAddr) ? ` (${mvprpGdsInfo.spotRdngRdnmDtlAddr})` : ""
            } else {
                rdngPlcNm = `${mvprpGdsInfo.hreadRegnSidoCdNm || ''} ${mvprpGdsInfo.hreadRegnSiguCdNm || ''}`
                rdngPlcNm += ` ${mvprpGdsInfo.hreadRegnEpmdongCdNm ||''}`
                rdngPlcNm += !scutilo.isEmpty(mvprpGdsInfo.hreadRegnRdongCdNm) ? ` ${mvprpGdsInfo.hreadRegnRdongCdNm}` : ""
                rdngPlcNm += ` ${mvprpGdsInfo.spotRdngDtlAddr || ''}`
            }
            pn_preRdngPlc.setValue(rdngPlcNm);
        }
        spn_preRdng.setValue(preRdngNm);
        /* 매각기일 */
        let dspslDxdy = `${scdateo.getFmtDate(mvprpGdsInfo.dxdyYmd,".")} ${scwin.timeFormat(mvprpGdsInfo.dxdyHm)} 부터`
        spn_dspslDxdy.setValue(dspslDxdy)
        /* 매각장소 */
        let dspslPlc = ""
        if (!scutilo.isEmpty(mvprpGdsInfo.mvprpDspslPlcAddrTypCd) && mvprpGdsInfo.mvprpDspslPlcAddrTypCd === 'R') {
            dspslPlc = `${mvprpGdsInfo.mvmPlaceRdnmSdNm || ''} ${mvprpGdsInfo.mvmPlaceRdnmSggNm || ''}`
            dspslPlc += ` ${mvprpGdsInfo.mvprpDspslPlcRdnmEmdNm || ""} ${mvprpGdsInfo.mvmPlaceRdnm}`
            dspslPlc += ` ${mvprpGdsInfo.mvprpDspslPlcDtlAddr || ""}`
            dspslPlc += !scutilo.isEmpty(mvprpGdsInfo.mvprpDspslPlcRdnmDtlAddr) ? ` (${mvprpGdsInfo.mvprpDspslPlcRdnmDtlAddr})` : ""
        } else {
            dspslPlc = `${mvprpGdsInfo.adongSdNm || ''} ${mvprpGdsInfo.adongSggNm || ''}`
            dspslPlc += ` ${mvprpGdsInfo.adongEmdNm || ''} ${mvprpGdsInfo.adongRiNm || ''}`
            dspslPlc += ` ${mvprpGdsInfo.mvprpDspslPlcDtlAddr || ''}`
        }
        spn_dspslPlc.setValue(dspslPlc);

        /* 공고유형 */
        let pbancTyp = pgjUtil.getSTGcodeSystemNm('PGJ','CORT_AUCTN_PBANC_TYP_CD',mvprpGdsInfo.cortAuctnPbancTypCd);
        spn_pbancTyp.setValue(pbancTyp);
        /* 매각장소유형 */
        if (atchmPlc.length>0) {
            let plcNm =""
            atchmPlc.forEach(data=>{
                if (data.mvprpAtchmPlcTypCd) {
                    plcNm += pgjUtil.getSTGcodeSystemNm('PGJ','MVPRP_ATCHM_PLC_TYP_CD',data.mvprpAtchmPlcTypCd)
                }
            })
            spn_dspslPlcTyp.setValue(plcNm);
        }
        /* 감정평가금액 */
        spn_aeeEvlAmt.setValue(mvprpGdsInfo.aeeEvlAmt || '0');
        /* 최저매각가격 */
        spn_lwsPrc.setValue(mvprpGdsInfo.lwsDspslPrc || '0');
        /* 물건 비고 */
        spn_gdsRmk.setValue(mvprpGdsInfo.dspslGdsRmk || "");

        /* 안내문구 */
        let tmpCtt = "매각날짜와 정확한 매각시간은 집행관사무실(" + baseInfo.cortTelnoLstCtt+ ")로 확인하시기 바랍니다.";
        tbx__artinfo.setValue(tmpCtt);

        scutilo.setPagingInfo(dma_pageInfo,pgl_mvprpGds,grd_mvprpGdsLst)
        spn_totalCnt.setValue(dma_pageInfo.get('totalCnt'));

    }

    //매각물품 번호
    if(dlt_mvprpGdsLst.getTotalRow() > 0){
        const startRowNo = Number(dma_pageInfo.get("startRowNo"));
        for(let i=0; i<dlt_mvprpGdsLst.getTotalRow();i++) {
            dlt_mvprpGdsLst.setCellData(i, "seq", i+startRowNo);
        }
    }

};

/**
 * 뒤로가기 버튼 클릭시 뒤로가기 이동
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.22.   나해준       [NELS]최초 생성
 *  2025.12.26.   공태은       [25A-PGJ-0053] 나의경매 자주쓰는검색 화면에서 페이지 이동시 검색조건이 초기화되는 현상 수정
 * ============= ============ ==========================
 */
scwin.prevButton = function(e) {
    let path = '';
    let detailInfo = {};
    let obj = {
        "dataObject": {
            "type": "json",
            "name": "param",
            "data": {}
        }
    };
    detailInfo = {
        prevInfo: {
            prevPgmId: scwin.prevPgmId
          , pageNum : scwin.pageNum
        },
        srchInfo: scwin.param.srchInfo
    }
    switch (scwin.prevPgmId) {
        case 'PGJ144M02':
            path = '/pgj/ui/pgj100/PGJ144M02.xml';
            break;
        case 'PGJ144M03':
            path = '/pgj/ui/pgj100/PGJ144M03.xml';
            break;
        case 'PGJ153M01':
            path = '/pgj/ui/pgj100/PGJ151M02.xml';
            break;
        case 'PGJ151F01':
            path = '/pgj/ui/pgj100/PGJ151M02.xml';
            break;
        case 'PGJ195M02':
            path = '/pgj/ui/pgj100/PGJ151M02.xml';
            break;

    }
    obj.dataObject.data = detailInfo
    $p.main().wfm_mainFrame.setSrc(path, obj);
};

scwin.printEvent = function(e) {

    let paramJSON = {};
    paramJSON.html = document.getElementById($p.getComponentById('grp_contests').id).innerHTML;

	var dataObject = {
			type : "json",
			data : paramJSON,
			name : "paramObj"
	};

    /* default popup size */
    const winW = window.innerWidth;
    const winH = window.innerHeight;
    const popupW = 1200;
    const popupH = 700;

    const popupX = (winW / 2) - (popupW / 2);
    const popupY = (winH / 2) - (popupH / 2);

	// 팝업의 옵션
	var options = {
			id: 'print',					// 팝업ID
			type: "browserPopup",			// 팝업 타입(wframePopup,browserPopup)
			width: popupW,				// 팝업 가로사이즈
			height: popupH,			// 팝업 세로사이즈
			top: popupY,					// 팝업 top위치
			left: popupX,				// 팝업 left위치
			popupName: "인쇄",				// 팝업 Name
			modal: false,					// 부모창이 안움직임(true)/부모창이 움직임(false)
			useIFrame: true,
			dataObject : dataObject
	};

	$p.openPopup("/pgj/ui/pgj100/PGJPrintContainer.xml", options);

};

//지도검색 팝업
scwin.mapPopUpOpen = function(e) {
    /********* Popup Settings *********/
    const winW = window.innerWidth;
    const winH = window.innerHeight;

    /* default popup size */
    const popupW = winW - 300;
    const popupH = winH - 100;

    const popupX = (winW/2) - (popupW/2);
    const popupY = (winH/2) - (popupH/2);

    const options = {
        id: "gdsMap",
        type: "browser",
        popupName: "지도",
        top:popupY,
        left:popupX,
        width:popupW,
        height:popupH,
        modal: false
    };
    paramObj = {};
    paramObj.pgmId = scwin.pgmId;
    paramObj.info = {
        csNo : dma_srchGdsinfo.get('csNo'),
        cortOfcCd : dma_srchGdsinfo.get('cortOfcCd'),
        dspslGdsSeq : dma_srchGdsinfo.get('dspslGdsSeq'),
        cortOfcNm : scwin.baseInfo.cortSptNm
    };

    com.win.openPopup("/pgj/ui/pgj100/PGJ152F00.xml",options,paramObj);
};

/**
 * 시간 셋팅 메서드
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.22.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.timeFormat = function(time){
    return scutilo.isEmpty(time) ? "" : time.slice(0,2).concat(":").concat(time.slice(2));
}

/**
 * 페이지 번호 클릭시 조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.11.13.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.pgl_mvprpGds_onviewchange = function(info) {
    dma_pageInfo.set( "pageNo" , info.newSelectedIndex );
    dma_pageInfo.set( "bfPageNo",info.oldSelectedIndex );
    scwin.mvprpGdsInfoPagingMain(false, scwin.pageSize);
};

/**
 * 페이지당 변경시 조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.11.13.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbx_mvprpGdsPage_onviewchange = function(info) {
    scwin.pageSize = info.newValue;
    scwin.mvprpGdsInfoPagingMain(true, info.newValue);
};
